// Parse and validate input
const input = $input.first().json;
const body = input.body || input;

if (!body.text) {
  return [{
    json: {
      success: false,
      error: { code: 'MISSING_TEXT', message: 'text is required' }
    }
  }];
}

if (!body.api_key) {
  return [{
    json: {
      success: false,
      error: { code: 'MISSING_API_KEY', message: 'api_key is required' }
    }
  }];
}

const threshold = body.threshold || 10000;
const textLength = body.text.length;

// If text is short enough, no chunking needed
if (textLength <= threshold) {
  return [{
    json: {
      success: true,
      needsChunking: false,
      segments: [{ index: 0, text: body.text, char_count: textLength }],
      total_segments: 1
    }
  }];
}

return [{
  json: {
    jobId: body.job_id,
    text: body.text,
    textLength: textLength,
    threshold: threshold,
    apiKey: body.api_key,
    context: body.context || {},
    needsChunking: true
  }
}];

// Parse Claude's chunking response
const input = $input.first().json;
const prevData = $('Parse Input').first().json;

try {
  const body = input.body || input;

  // Check for API error
  if (body.error) {
    return [{
      json: {
        success: false,
        error: {
          code: 'CLAUDE_ERROR',
          message: body.error.message || 'Smart Split API error'
        }
      }
    }];
  }

  const content = body.content?.[0]?.text || '';

  if (!content) {
    return [{
      json: {
        success: false,
        error: {
          code: 'EMPTY_RESPONSE',
          message: 'Smart Split returned empty response'
        }
      }
    }];
  }

  // Try to parse JSON from response
  let jsonStr = content;
  const jsonMatch = content.match(/```json\n?([\s\S]*?)\n?```/);
  if (jsonMatch) {
    jsonStr = jsonMatch[1];
  }

  const parsed = JSON.parse(jsonStr);
  const chunks = parsed.chunks || [];

  if (chunks.length === 0) {
    return [{
      json: {
        success: false,
        error: {
          code: 'NO_CHUNKS',
          message: 'Smart Split returned no chunks'
        }
      }
    }];
  }

  // Format segments
  const segments = chunks.map((chunk, idx) => ({
    index: chunk.index !== undefined ? chunk.index : idx,
    text: chunk.text,
    char_count: chunk.char_count || chunk.text.length
  }));

  return [{
    json: {
      success: true,
      segments: segments,
      total_segments: segments.length,
      method: 'claude_semantic'
    }
  }];
} catch (e) {
  return [{
    json: {
      success: false,
      error: {
        code: 'PARSE_ERROR',
        message: 'Failed to parse Smart Split response: ' + e.message
      }
    }
  }];
}

